// Parse Event — VigilaTeh WhatsApp notifications
// Input: webhook Traccar {event, device, position}
// Output: {rawType, normalizedType, deviceId, deviceName, eventTime, label}

const raw = $input.first().json;
const data = raw.body ?? raw;   // webhook envuelve en .body; fallback por si viene directo

const event    = data.event    || {};
const device   = data.device   || {};
const position = data.position || {};

const rawType = event.type;
const eventTime = event.eventTime;

// ---------- normalizeEventType ----------
function normalizeEventType(rawType, event) {
  // Ignición
  if (rawType === 'ignitionOn')  return 'ignitionOn';
  if (rawType === 'ignitionOff') return 'ignitionOff';

  // commandResult → cut off / restore
  if (rawType === 'commandResult') {
    const result = String(event?.attributes?.result || '').toLowerCase();
    if (result.includes('cut off')) return 'engineCutSent';
    if (result.includes('restore')) return 'engineCutRestored';
  }

  // Estado de conexión
  if (rawType === 'deviceOnline')  return 'deviceOnline';
  if (rawType === 'deviceOffline') return 'deviceOffline';
  if (rawType === 'deviceUnknown') return 'deviceUnknown';

  // Todo lo demás se descarta
  return null;
}

const normalizedType = normalizeEventType(rawType, event);

// ---------- Labels por evento ----------
const LABELS = {
  ignitionOn:        '🟢 Ignición encendida',
  ignitionOff:       '🔴 Ignición apagada',
  engineCutSent:     '🛑 Paro de motor activado',
  engineCutRestored: '✅ Motor restablecido',
  deviceOnline:      '🟢 Equipo reconectado',
  deviceOffline:     '🔴 Equipo desconectado',
  deviceUnknown:     '⚠️ Equipo sin señal',
};

const label = normalizedType ? (LABELS[normalizedType] || null) : null;

return [{
  json: {
    rawType,
    normalizedType,
    deviceId:   device.id,
    deviceName: device.name,
    eventTime,
    label,
  }
}];

const eventData = $('Parse Event').first().json;

return $input.all().flatMap((item) => {
  const user = item.json;
  let attrs = user.attrs || {};
  if (typeof attrs === 'string') {
    try { attrs = JSON.parse(attrs); } catch { return []; }
  }
  let subscribedEvents = attrs.whatsappEvents || [];
  if (typeof subscribedEvents === 'string') {
    try { subscribedEvents = JSON.parse(subscribedEvents); } catch { return []; }
  }
  if (!Array.isArray(subscribedEvents) || !subscribedEvents.includes(eventData.normalizedType)) return [];

  let timeStr = eventData.eventTime;
  try {
    timeStr = new Date(eventData.eventTime).toLocaleString('es-MX', {
      timeZone: 'America/Mexico_City',
      day: '2-digit', month: '2-digit', year: 'numeric',
      hour: '2-digit', minute: '2-digit'
    });
  } catch {}

  const message = `*VigilaTeh* 🚗\n\n${eventData.label}\n\n📱 ${eventData.deviceName}\n🕐 ${timeStr}`;
  return [{ json: { phone: user.phone, message, userId: user.id, normalizedType: eventData.normalizedType } }];
});
